using LayoutInventoryJournal::Detail::Failure;using LayoutInventoryJournal::Detail::Require;
using LayoutInventoryJournal::Detail::Q;using LayoutInventoryJournal::Detail::Hex;using LayoutInventoryJournal::Detail::Literal;using LayoutInventoryJournal::Detail::Unhex;using LayoutInventoryJournal::Detail::Canonical;
inline void Schema(Database& db){auto r=Q(db,"SELECT engine FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='housing_layout_mixed_batches'");Require(r.RowCount()==1&&r.begin()[0]&&std::string(r.begin()[0])=="InnoDB",Error::Disabled);}
// Version5 is a SERVER-normalized single direct3424 count, not a new
// client file-layout target. Its exact placed container is part of the plan.
inline bool CrateCountPlan(const Binding& b){return b.plan.size()>=4&&b.plan[0]==5&&!b.plan[1]&&!b.plan[2]&&!b.plan[3];}
inline LayoutCrate::Allocation CrateDestination(const Binding& b,const LayoutWire::Load* wire=nullptr){try{
 if(!CrateCountPlan(b))return {};CustodyCodec::Reader r{b.plan};r.N(4);const auto estate=r.N(4),yard=r.N(4),room=r.N(4),house=r.N(8),zone=r.N(4),version=r.N(1),instance=r.N(2),inside=r.N(1);(void)version;
 if(!estate||!yard||yard==UINT32_MAX||room==UINT32_MAX||bool(room)!=bool(house)||!zone||!instance||instance>32000||inside>1||(wire&&(wire->yard_estate_id!=yard||LayoutWire::ContextHouseEstateId(*wire)!=room)))return {};
 auto allocation=CrateBinding::DecodeAllocation(r.Blob(512));if(!allocation)return {};const auto& a=allocation.value;const auto& c=a.binding;if(a.packed||a.inventory_character_id||a.inventory_slot_id||!c.custody_id||(c.parent_native_estate_id!=yard&&c.parent_native_estate_id!=room))return {};return std::make_shared<const CrateBinding::Allocation>(std::move(allocation.value));
 }catch(...){return {};}}
inline bool CrateDestinationMatches(const Binding& b,const LayoutMixed::Outcome& o){if(!CrateCountPlan(b))return true;auto target=CrateDestination(b);if(!target||o.inventory||!o.retained_tokens.empty()||!o.property||o.property->steps.size()!=1)return false;const auto& s=o.property->steps.front();return s.action==LayoutProperty::Action::SplitToCrate&&s.changes.size()==3&&s.changes.back().before&&LayoutCrate::Same(target,s.changes.back().before->crate);}
inline std::optional<LayoutWire::Load> Wire(const Binding& b){if(!LayoutInventoryJournal::Detail::Key(b.request_key)||b.plan.empty()||b.plan.size()>LayoutBatch::MaximumPlanBytes)return {};auto wire=LayoutWire::DecodeLoad(b.wire.data(),b.wire.size());if(!wire||wire->operations.empty())return {};auto destination=CrateDestination(b,&*wire);if(CrateCountPlan(b)){if(!destination||wire->operations.size()!=1)return {};auto* count=std::get_if<LayoutWire::ItemOperation>(&wire->operations[0]);if(!count||!count->quantity||count->target_estate_id!=destination->binding.native_estate_id)return {};}for(const auto& operation:wire->operations){uint32_t target=0;if(const auto* p=std::get_if<LayoutWire::PlacementOperation>(&operation)){target=p->target_estate_id;if(p->source_kind==0){if(p->source_estate_id!=UINT32_MAX||p->native_item_id!=UINT32_MAX||p->source_slots[0]<23||p->source_slots[0]>33||p->source_slots[2]!=0xffff||(p->source_slots[1]!=0xffff&&p->source_slots[1]>=EQ::invbag::SLOT_COUNT))return {};}else if(p->source_kind!=0xff||p->source_slots!=std::array<uint16_t,3>{0xffff,0xffff,0xffff}||!LayoutMixed::Detail::Id(p->source_estate_id)||!LayoutMixed::Detail::Id(p->native_item_id))return {};}else{const auto& item=std::get<LayoutWire::ItemOperation>(operation);target=item.target_estate_id;if(!LayoutMixed::Detail::Id(item.source_estate_id)||!LayoutMixed::Detail::Id(item.native_item_id))return {};}if(!LayoutMixed::Detail::Id(target)||(target!=wire->yard_estate_id&&target!=wire->house_estate_id&&(!destination||target!=destination->binding.native_estate_id)))return {};}return wire;}
inline void OtherFamilies(Database& db,const std::string& key){for(const auto* table:{"housing_live_item_receipts","housing_layout_batches","housing_layout_inventory_batches"}){auto schema=Q(db,std::string("SELECT engine FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='")+table+"'");if(!schema.RowCount())continue;Require(schema.RowCount()==1&&schema.begin()[0]&&std::string(schema.begin()[0])=="InnoDB",Error::DatabaseFailure);auto r=Q(db,std::string("SELECT request_key FROM ")+table+" WHERE request_key="+Literal(key)+" FOR UPDATE");Require(!r.RowCount(),Error::Conflict);}}
inline LiveItems::Result<Receipt> Lookup(Database& db,const Binding& b,const LiveItems::Lease& current){OtherFamilies(db,b.request_key);auto rows=Q(db,"SELECT format_version,character_id,account_id,lease_epoch,HEX(session_key),HEX(binding_blob),HEX(outcome_blob),applied FROM housing_layout_mixed_batches WHERE request_key="+Literal(b.request_key)+" FOR UPDATE");if(!rows.RowCount())return {{},Error::NotFound};Require(rows.RowCount()==1,Error::DatabaseFailure);auto r=rows.begin();for(size_t i=0;i<8;++i)Require(r[i],Error::DatabaseFailure);Require(std::string(r[0])=="1",Error::DatabaseFailure);Require(std::stoul(r[1])==b.lease.actor.character_id&&std::stoul(r[2])==b.lease.actor.account_id,Error::Unauthorized);Require(std::stoull(r[3])==b.lease.epoch&&Unhex(r[4],96)==Bytes(b.lease.session_key.begin(),b.lease.session_key.end()),Error::StaleLease);Require(Unhex(r[5],LayoutBatch::MaximumPlanBytes+NeighborhoodWire::MaximumPayload+512)==Canonical(b),Error::Conflict);auto outcome=LayoutMixed::Decode(Unhex(r[6],LayoutMixed::MaximumBytes));auto wire=Wire(b);Require(outcome&&wire&&LayoutMixed::MatchesWire(*wire,*outcome)&&CrateDestinationMatches(b,*outcome),Error::DatabaseFailure);Require(std::string(r[7])=="0"||std::string(r[7])=="1",Error::DatabaseFailure);const bool applied=std::string(r[7])=="1";Require(applied?current.pending_key!=b.request_key:current.pending_key==b.request_key,Error::Conflict);if(!applied){auto valid=LayoutMixed::ValidateFinalUnderTransaction(db,b.lease,*outcome,b.request_key);if(!valid)return {{},valid.error};}return {{std::move(*outcome),applied,true},Error::None};}
inline bool PropertyPrepared(const LayoutMixed::Outcome& outcome,const LayoutProperty::State* state){
 if(!outcome.property)return !state||state->split_units.empty();if(!state)return false;
 std::map<uint64_t,const LayoutPropertyOutcome::Snapshot*> original,created;
 for(const auto& step:outcome.property->steps)for(const auto& d:step.changes){if(d.before&&!created.count(d.before->placement.stored.custody_id))original.emplace(d.before->placement.stored.custody_id,&*d.before);if(!d.before&&d.after)created.emplace(d.after->placement.stored.custody_id,&*d.after);}
 for(const auto& source:outcome.property_sources){auto witness=state->witnesses.find({source.estate,source.item});if(witness==state->witnesses.end()||witness->second.custody_id!=source.custody||witness->second.guid!=source.guid)return false;}
 for(const auto& entry:original){bool matched=false;for(const auto& w:state->witnesses)if(w.second.custody_id==entry.first&&w.second.instance&&CustodyCodec::Encode(w.second.row)==CustodyCodec::Encode(entry.second->placement.stored.row)&&InventoryProjection::Matches(w.second.row,*w.second.instance)&&LayoutCrateMember::SameOrigin(w.second.member,entry.second->member)&&LayoutCrate::Same(w.second.crate,entry.second->crate)&&LayoutCrate::Matches(w.second.crate,w.second.instance)&&LayoutHouse::Same(w.second.house,entry.second->house)&&LayoutHouse::Matches(w.second.house,w.second.instance)){const auto text=std::to_string(w.second.instance->GetSerialNumber());if(w.second.guid==std::string(16-text.size(),'0')+text){matched=true;break;}}if(!matched)return false;}
 for(const auto& entry:original)if(entry.second->member){const auto id=entry.second->member->container->binding.custody_id;auto container=original.find(id);if(container==original.end()||!container->second->crate)return false;bool bound=false;for(const auto& w:state->witnesses)if(w.second.custody_id==entry.first&&w.second.member&&LayoutCrateMember::SameOrigin(w.second.member,entry.second->member)&&LayoutCrate::Same(w.second.member->container,container->second->crate)){bound=true;break;}if(!bound)return false;}
 if(created.size()!=state->split_units.size())return false;for(const auto& entry:created){auto item=state->split_units.find(entry.first);if(item==state->split_units.end()||!item->second||item->second->GetSerialNumber()!=entry.second->runtime_serial||!InventoryProjection::Matches(entry.second->placement.stored.row,*item->second))return false;}return true;
}
