inline LiveItems::Result<Receipt> ReadUnderTransaction(Database& db,bool enabled,const Binding& b,LiveItems::InventorySessionFence& fence){if(!enabled)return {{},Error::Disabled};if(!Detail::Wire(b))return {{},Error::InvalidArgument};try{auto current=LiveItems::Service::AuthenticateUnderTransaction(db,true,b.lease,fence);if(!current)return {{},current.error};Detail::Schema(db);return Detail::Lookup(db,b,current.value);}catch(const Detail::Failure& e){return {{},e.error};}catch(...){return {{},Error::DatabaseFailure};}}
// Parent coordinator owns authorization and transaction. Real prepared memory,
// exact wire/result coverage and SQL postimages are independently checked here.
// A failure after earlier writes requires whole rollback and discarded State.
inline LiveItems::Result<Receipt> CompleteUnderTransaction(Database& db,bool enabled,const Binding& b,const LayoutMixed::Outcome& outcome,const LayoutInventory::Plan* plan,const LayoutInventory::Prepared* prepared,EQ::InventoryProfile* inv,const LayoutProperty::State* property,LiveItems::InventorySessionFence& fence){
 if(!enabled)return {{},Error::Disabled};auto wire=Detail::Wire(b);if(!wire)return {{},Error::InvalidArgument};try{auto current=LiveItems::Service::AuthenticateUnderTransaction(db,true,b.lease,fence);if(!current)return {{},current.error};Detail::Schema(db);auto old=Detail::Lookup(db,b,current.value);if(old)return old;if(old.error!=Error::NotFound)return old;Detail::Require(current.value.pending_key.empty(),Error::PendingApplication);Detail::Require(LayoutMixed::MatchesWire(*wire,outcome)&&Detail::CrateDestinationMatches(b,outcome));Detail::Require(Detail::PropertyPrepared(outcome,property),Error::UnheldFence);
  if(outcome.inventory){Detail::Require(plan&&prepared&&inv&&LayoutInventory::PreparedMatches(*plan,*prepared,b.lease,*inv,fence),Error::UnheldFence);std::vector<LiveItems::LayoutUnitPlacement> placements;for(const auto& p:outcome.inventory->pieces)placements.push_back(p.placement);auto actual=LayoutInventory::MakeOutcome(*plan,*prepared,outcome.inventory->inventory,placements);Detail::Require(LayoutInventory::EncodeOutcome(actual)==LayoutInventory::EncodeOutcome(*outcome.inventory));}else Detail::Require((!plan||plan->uses.empty())&&(!prepared||prepared->units.empty()));
  Detail::Require(prepared||outcome.retained_tokens.empty(),Error::UnheldFence);if(prepared){Detail::Require(prepared->retained_tokens.size()==outcome.retained_tokens.size(),Error::UnheldFence);for(size_t i=0;i<outcome.retained_tokens.size();++i){const auto& t=outcome.retained_tokens[i];const auto& w=prepared->retained_tokens[i];Detail::Require(LayoutRetained::Matches(t,w)&&inv&&inv->GetItem(int16_t(w.row.values.slot_id))==w.original&&fence.LayoutSourceMatches(w.row,w.serial),Error::UnheldFence);}}
  LayoutRetained::PublishHouses(db,outcome.retained_tokens,b.request_key);
  auto valid=LayoutMixed::ValidateFinalUnderTransaction(db,b.lease,outcome,b.request_key);if(!valid)return {{},valid.error};const auto bytes=LayoutMixed::Encode(outcome);const auto& l=b.lease;auto saved=Detail::Q(db,"INSERT INTO housing_layout_mixed_batches(request_key,format_version,character_id,account_id,lease_epoch,session_key,binding_blob,outcome_blob,applied) VALUES("+Detail::Literal(b.request_key)+",1,"+std::to_string(l.actor.character_id)+","+std::to_string(l.actor.account_id)+","+std::to_string(l.epoch)+","+Detail::Literal(l.session_key)+",x'"+Detail::Hex(Detail::Canonical(b))+"',x'"+Detail::Hex(bytes)+"',0)");Detail::Require(saved.RowsAffected()==1,Error::DatabaseFailure);auto pending=Detail::Q(db,"UPDATE housing_live_item_leases SET pending_key="+Detail::Literal(b.request_key)+" WHERE character_id="+std::to_string(l.actor.character_id)+" AND pending_key IS NULL");Detail::Require(pending.RowsAffected()==1,Error::PendingApplication);return {{outcome,false,false},Error::None};
 }catch(const Detail::Failure& e){return {{},e.error};}catch(const std::invalid_argument&){return {{},Error::InvalidArgument};}catch(...){return {{},Error::DatabaseFailure};}
}
// Exact pending-family lookup component only. The real supervisor-linked writer
// death proof/reconciliation owns any release; this grants none by itself.
inline LiveItems::Result<Receipt> ReadPendingForRestartUnderTransaction(Database& db,const LiveItems::Lease& lease){if(!LayoutInventoryJournal::Detail::Key(lease.pending_key))return {{},Error::NotFound};try{LayoutPropertyOutcome::Detail::Transaction(db);auto schema=Detail::Q(db,"SELECT engine FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='housing_layout_mixed_batches'");if(!schema.RowCount()){auto absent=db.QueryDatabase(std::string("SELECT request_key FROM housing_layout_mixed_batches WHERE 1=0"),false);if(!absent.Success()&&absent.ErrorNumber()==1146)return {{},Error::NotFound};return {{},Error::DatabaseFailure};}Detail::Schema(db);auto rows=Detail::Q(db,"SELECT HEX(binding_blob) FROM housing_layout_mixed_batches WHERE request_key="+Detail::Literal(lease.pending_key)+" FOR UPDATE");if(!rows.RowCount())return {{},Error::NotFound};Detail::Require(rows.RowCount()==1,Error::DatabaseFailure);auto bytes=Detail::Unhex(rows.begin()[0],LayoutBatch::MaximumPlanBytes+NeighborhoodWire::MaximumPayload+512);CustodyCodec::Reader r{bytes};Detail::Require(r.N(4)==1,Error::DatabaseFailure);Binding b;b.request_key=r.Text(96);b.lease.actor.character_id=r.N(4);b.lease.actor.account_id=r.N(4);b.lease.epoch=r.N(8);b.lease.session_key=r.Text(96);for(auto& byte:b.lease.token)byte=r.N(1);b.wire=r.Blob(NeighborhoodWire::MaximumPayload);b.plan=r.Blob(LayoutBatch::MaximumPlanBytes);Detail::Require(r.at==bytes.size()&&Detail::Canonical(b)==bytes&&Detail::Wire(b),Error::DatabaseFailure);Detail::Require(b.request_key==lease.pending_key&&b.lease.actor.character_id==lease.actor.character_id&&b.lease.actor.account_id==lease.actor.account_id&&b.lease.epoch==lease.epoch&&b.lease.session_key==lease.session_key&&b.lease.token==lease.token,Error::StaleLease);auto result=Detail::Lookup(db,b,lease);if(result&&result.value.applied)return {{},Error::Conflict};return result;}catch(const Detail::Failure& e){return {{},e.error};}catch(...){return {{},Error::DatabaseFailure};}}
